#include <bits/stdc++.h>
using namespace std;

long long modPow(long long base, int exp, long long mod) {
    long long result = 1;
    long long b = base % mod;
    int e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

